// Compiles the homepage's example with the real compiler and writes the result for the page,
// so the "Compiled" view can never drift from what @fluixi/compiler produces. The JSX and html``
// versions must compile to the same code; when they stop doing so, the build fails rather than
// the page claiming something false.
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const { createVitePlugin } = await import(join(root, '../packages/compiler/dist/integrations.mjs'));

export const JSX_SOURCE = `function Stepper({ label, step = 1 }) {
  const count = $signal(0);
  const total = $memo(() => count() * step);

  return (
    <button onClick={() => count.set((c) => c + 1)}>
      {label}: {total()}
    </button>
  );
}`;

export const HTML_SOURCE = `function Stepper({ label, step = 1 }) {
  const count = $signal(0);
  const total = $memo(() => count() * step);

  return html\`
    <button @click=\${() => count.set((c) => c + 1)}>
      \${label}: \${total()}
    </button>
  \`;
}`;

async function compile(code, id, options) {
  for (const plugin of [createVitePlugin(options)].flat()) {
    const transform = plugin.transform?.handler ?? plugin.transform;
    if (!transform) continue;
    const ctx = { warn() {}, error(e) { throw e; }, environment: { name: 'client' } };
    const out = await transform.call(ctx, code, join(root, 'src/generated', id));
    if (out) return typeof out === 'string' ? out : out.code;
  }
  throw new Error(`[hero-compile] ${id} was not transformed`);
}

// What both syntaxes must share: the setup before `return` and the statements that build the DOM.
function body(code) {
  const fn = code.slice(code.indexOf('function Stepper('));
  const dom = fn.match(/\(\) => \{ ([\s\S]*?) return _el\$; \}/);
  if (!dom) throw new Error('[hero-compile] the compiled example has an unexpected shape');
  return `${fn.slice(0, fn.indexOf('return')).trim()}\n${dom[1]}`;
}

// The DOM-building closure comes out on one line; give each statement its own.
function format(code) {
  return code
    .replace(/\/\/# sourceMappingURL=.*$/m, '')
    .replace(/\(\(\) => \{ ([\s\S]*?) return _el\$; \}\)\(\)/, (_, inner) => {
      const lines = inner.split(/; (?=const |addDelegatedEventListener|insert|_el\$)/).map((l) => `    ${l.replace(/;$/, '')};`);
      return `(() => {\n${lines.join('\n')}\n    return _el$;\n  })()`;
    })
    .replace(/return \(\s*\n\s*\(\(\) => \{/, 'return (() => {')
    .replace(/\}\)\(\)\s*\n\s*\);/, '})();')
    .trim();
}

const jsx = await compile(JSX_SOURCE, 'stepper.tsx', {});
const html = await compile(`import { html } from '@fluixi/core';\n${HTML_SOURCE}`, 'stepper.ts', { format: 'html' });
if (body(jsx) !== body(html)) {
  throw new Error('[hero-compile] the JSX and html`` examples no longer compile to the same code; fix the example or the page text.');
}

const out = join(root, 'src/generated/hero.ts');
mkdirSync(dirname(out), { recursive: true });
writeFileSync(
  out,
  `// Generated by scripts/hero-compile.mjs from @fluixi/compiler. Do not edit.\n` +
    `export const HERO_JSX = ${JSON.stringify(JSX_SOURCE)};\n` +
    `export const HERO_HTML = ${JSON.stringify(HTML_SOURCE)};\n` +
    `export const HERO_COMPILED = ${JSON.stringify(format(jsx))};\n`,
);
console.log('  ✓ hero example compiled (JSX and html`` match)');
